# T009: fonts and text.
#
# Expected values, per test/README.md, from three independent sources:
# 1. Oracle fixtures under test/reference/font_* generated by the pinned
#    upstream (tools/oracle/build.sh fonts): metric/kerning TSVs, layout
#    TSVs (IEEE754 hex) and 14 rendered images mirroring upstream test
#    blocks (test_fonts.nim / test_contexts.nim).
# 2. Upstream-pinned assertions (test_fonts.nim L27/L34/L1049,
#    test_contexts.nim L495): layoutBounds("Word") == (56, 28),
#    layoutBounds("Word\n") == (56, 56), Roboto T,e kerning == -99.0,
#    measureText("Hello world") @12 == 60.
# 3. Hand-derived OpenType values for the synthetic mini font below
#    (composite + empty glyphs, OS/2 v1/v2, kern v0/v1, loca fmt 0/1,
#    hmtx trailing LSBs, UTF-16BE name).

using Test
using SHA
using .VetraRef

const FONT_DIR = joinpath(@__DIR__, "..", ".reference", "upstream", "tests", "fonts")
const ROBO = joinpath(FONT_DIR, "Roboto-Regular_1.ttf")
const UBU = joinpath(FONT_DIR, "Ubuntu-Regular_1.ttf")
const INTER = joinpath(FONT_DIR, "Inter-Regular.ttf")

f32hex(h::AbstractString) = Base.bitcast(Float32, parse(UInt32, h; base = 16))

function fontrows(tag::String)
    return VetraRef.read_table(tag)[3]
end

function fontmeta(tag::String)
    return VetraRef.read_table(tag)[1]
end

function throws_arg(f, msg::String)
    try
        f()
        return false
    catch e
        return e isa ArgumentError && e.msg == msg
    end
end

@testset "T009 fonts and text" begin

    @testset "font provenance (sha256 + license recorded in fixtures)" begin
        meta = fontmeta("font_roboto_metrics")
        @test meta["font_sha256"] ==
            VetraRef.hexdigest(sha256(read(ROBO)))
        @test meta["font_license"] == "Apache License 2.0"
        meta = fontmeta("font_ubuntu_metrics")
        @test meta["font_sha256"] ==
            VetraRef.hexdigest(sha256(read(UBU)))
        @test meta["font_license"] == "Ubuntu Font License 1.0"
    end

    @testset "metrics: per-rune glyph ids and advances (oracle rows)" begin
        for (tag, path) in [("font_roboto_metrics", ROBO),
            ("font_ubuntu_metrics", UBU)]
            rows = fontrows(tag)
            @test !isempty(rows)
            tf = readTypeface(path)
            for r in rows
                cp = parse(UInt32, r[1])
                gid = parse(Int, r[2])
                adv = f32hex(r[3])
                @test Int(tf.opentype.cmap.runeToGlyphId[cp]) == gid
                @test isequal(getAdvance(tf.opentype, cp), adv)
            end
        end
        # Upstream-pinned rows: glyph ids (gposprobe) and advances.
        tf = readTypeface(ROBO)
        @test scale(tf) == 2048f0
        @test Int(tf.opentype.cmap.runeToGlyphId[UInt32(84)]) == 56   # 'T'
        @test Int(tf.opentype.cmap.runeToGlyphId[UInt32(101)]) == 73  # 'e'
        @test isequal(getAdvance(tf.opentype, UInt32(87)), 1817f0)  # 'W'
        @test isequal(getAdvance(tf.opentype, UInt32(111)), 1168f0) # 'o'
        @test name(tf) == "Roboto-Regular"
    end

    @testset "kerning (oracle rows)" begin
        for (tag, path) in [("font_roboto_kerning", ROBO),
            ("font_ubuntu_kerning", UBU)]
            rows = fontrows(tag)
            @test !isempty(rows)
            tf = readTypeface(path)
            for r in rows
                left = parse(UInt32, r[1])
                right = parse(UInt32, r[2])
                @test isequal(getKerningAdjustment(tf, left, right),
                    f32hex(r[3]))
            end
        end
        # test_fonts.nim L1049: Roboto T,e == -99.0; oracle probe W,o = -31.0
        tf = readTypeface(ROBO)
        @test isequal(getKerningAdjustment(tf, UInt32(84), UInt32(101)), -99f0)
        @test isequal(getKerningAdjustment(tf, UInt32(87), UInt32(111)), -31f0)
        # Missing rune -> 0 (both sides and single side).
        @test isequal(getKerningAdjustment(tf, UInt32(0x1f600), UInt32(101)),
            0f0)
        @test isequal(getKerningAdjustment(tf, UInt32(84), UInt32(0x1f600)),
            0f0)
    end

    @testset "layout: typeset positions/rects + bounds (oracle rows)" begin
        SCEN = Dict(
            "basic1" => (ROBO, 72, "asdf", 0f0, 0f0, LeftAlign, TopAlign, true,
                -1f0),
            "basic2" => (ROBO, 72, "A cow", 0f0, 0f0, LeftAlign, TopAlign, true,
                -1f0),
            "basic3" => (ROBO, 24, "A bit of text HERE", 0f0, 0f0, LeftAlign,
                TopAlign, true, -1f0),
            "basic4" => (ROBO, 24, "Line height", 0f0, 0f0, LeftAlign,
                TopAlign, true, 100f0),
            "basic7" => (ROBO, 24, "First line\nSecond line", 0f0, 0f0,
                LeftAlign, TopAlign, true, -1f0),
            "basic8" => (ROBO, 24, "Wrapping text to new line", 200f0, 0f0,
                LeftAlign, TopAlign, true, -1f0),
            "basic8b" => (ROBO, 24,
                "Long words: Supercalifragilisticexpialidocious\n" *
                "Antidisestablishmentarianism", 100f0, 0f0, LeftAlign,
                TopAlign, true, -1f0),
            "word" => (ROBO, 24, "Word", 0f0, 0f0, LeftAlign, TopAlign, true,
                -1f0),
            "word_lf" => (ROBO, 24, "Word\n", 0f0, 0f0, LeftAlign, TopAlign,
                true, -1f0),
            "ctx_fill1" => (ROBO, 50, "Hello world", 0f0, 0f0, LeftAlign,
                TopAlign, true, -1f0),
            "synth_center" => (ROBO, 24, "Centered text", 200f0, 0f0,
                CenterAlign, TopAlign, true, -1f0),
            "synth_right" => (ROBO, 24, "Right aligned", 200f0, 0f0,
                RightAlign, TopAlign, true, -1f0),
            "synth_vmid" => (ROBO, 24, "Vmid", 0f0, 100f0, LeftAlign,
                MiddleAlign, true, -1f0),
            "synth_vbot" => (ROBO, 24, "Vbot", 0f0, 100f0, LeftAlign,
                BottomAlign, true, -1f0),
            "synth_nowrap" => (ROBO, 24, "No wrap here", 200f0, 0f0,
                LeftAlign, TopAlign, false, -1f0),
            "ubuntu1" => (UBU, 24, "Word", 0f0, 0f0, LeftAlign, TopAlign, true,
                -1f0),
            "ubuntu2" => (UBU, 24, "Wrapping text to new line", 200f0, 0f0,
                LeftAlign, TopAlign, true, -1f0)
        )
        oracle = Dict{String,Vector{Vector{String}}}()
        for r in fontrows("font_layouts")
            push!(get!(oracle, r[1], Vector{Vector{String}}()), r[2:end])
        end
        obounds = Dict(r[1] => (f32hex(r[2]), f32hex(r[3])) for
            r in fontrows("font_layout_bounds"))

        for (id, (path, size, text, bx, by, ha, va, wrap, lh)) in
            sort(collect(pairs(SCEN)))
            tf = readTypeface(path)
            f = newFont(tf)
            f.size = Float32(size)
            if lh > 0
                f.lineHeight = lh
            end
            arr = typeset(f, text; bounds = Vec2(bx, by), hAlign = ha,
                vAlign = va, wrap = wrap)
            rows = oracle[id]
            @test length(rows) == length(arr.runes)
            for (i, row) in enumerate(rows)
                @test Int(arr.runes[i]) == parse(Int, row[1])
                @test isequal(arr.positions[i].x, f32hex(row[2]))
                @test isequal(arr.positions[i].y, f32hex(row[3]))
                @test isequal(arr.selectionRects[i].x, f32hex(row[4]))
                @test isequal(arr.selectionRects[i].y, f32hex(row[5]))
                @test isequal(arr.selectionRects[i].w, f32hex(row[6]))
                @test isequal(arr.selectionRects[i].h, f32hex(row[7]))
            end
            b = layoutBounds(arr)
            @test isequal(b.x, obounds[id][1])
            @test isequal(b.y, obounds[id][2])
        end

        # test_fonts.nim L27/L34 (upstream doAsserts).
        f = newFont(readTypeface(ROBO))
        f.size = 24f0
        @test layoutBounds(f, "Word") == Vec2(56f0, 28f0)
        @test layoutBounds(f, "Word\n") == Vec2(56f0, 56f0)
    end

    @testset "rendered text: 0 pixel mismatches vs oracle" begin
        tf = readTypeface(ROBO)
        tf2 = readTypeface(UBU)

        function white200()
            img = newImage(200, 100)
            fill(img, rgb(255, 255, 255))
            return img
        end

        function check0(tag, img)
            ref, wh = VetraRef.read_raw(tag)
            @test VetraRef.verify_checksum(tag)
            @test wh == (img.width, img.height)
            @test VetraRef.compare_pixels(img.data, ref, wh).count == 0
        end

        @testset "image_fill (Roboto 64 'fill')" begin
            f = newFont(tf); f.size = 64f0
            img = white200()
            fillText(img, f, "fill")
            check0("font_image_fill", img)
        end
        @testset "image_stroke (Roboto 64 'stroke')" begin
            f = newFont(tf); f.size = 64f0
            img = white200()
            strokeText(img, f, "stroke")
            check0("font_image_stroke", img)
        end
        @testset "basic1 (Roboto 72 'asdf')" begin
            f = newFont(tf); f.size = 72f0
            img = white200()
            fillText(img, f, "asdf")
            check0("font_basic1", img)
        end
        @testset "basic2 (Roboto 72 'A cow')" begin
            f = newFont(tf); f.size = 72f0
            img = white200()
            fillText(img, f, "A cow")
            check0("font_basic2", img)
        end
        @testset "basic3 (Roboto 24 'A bit of text HERE')" begin
            f = newFont(tf); f.size = 24f0
            img = white200()
            fillText(img, f, "A bit of text HERE")
            check0("font_basic3", img)
        end
        @testset "basic4 (Roboto 24 lineHeight 100 'Line height')" begin
            f = newFont(tf); f.size = 24f0; f.lineHeight = 100f0
            img = white200()
            fillText(img, f, "Line height")
            check0("font_basic4", img)
        end
        @testset "basic7 (two lines, defaultLineHeight translate)" begin
            f = newFont(tf); f.size = 24f0
            img = white200()
            fillText(img, f, "First line")
            fillText(img, f, "Second line",
                transform = translate(Vec2(0f0, defaultLineHeight(f))))
            check0("font_basic7", img)
        end
        @testset "basic8 (wrap at 200)" begin
            f = newFont(tf); f.size = 24f0
            img = white200()
            fillText(img, f, "Wrapping text to new line",
                bounds = Vec2(200f0, 0f0))
            check0("font_basic8", img)
        end
        @testset "basic8b (long words, wrap at 100)" begin
            f = newFont(tf); f.size = 24f0
            img = white200()
            fillText(img, f,
                "Long words: Supercalifragilisticexpialidocious\n" *
                "Antidisestablishmentarianism", bounds = Vec2(100f0, 0f0))
            check0("font_basic8b", img)
        end
        @testset "underline1 (wrap, underline)" begin
            f = newFont(tf); f.size = 24f0; f.underline = true
            img = white200()
            fillText(img, f, "Wrapping text to new line",
                bounds = Vec2(200f0, 0f0))
            check0("font_underline1", img)
        end
        @testset "strikethrough1 (wrap, strikethrough)" begin
            f = newFont(tf); f.size = 24f0; f.strikethrough = true
            img = white200()
            fillText(img, f, "Wrapping text to new line",
                bounds = Vec2(200f0, 0f0))
            check0("font_strikethrough1", img)
        end
        @testset "ctx fillText (300x150, size 50, save/restore)" begin
            img = newImage(300, 150)
            ctx = Context(img)
            ctx.font = ROBO
            ctx.fontSize = 50f0
            save(ctx)
            ctx.fontSize = 30f0
            restore(ctx)
            fillText(ctx, "Hello world", 50f0, 90f0)
            check0("font_ctx_fill1", img)
        end
        @testset "ctx strokeText (300x150, size 50)" begin
            img = newImage(300, 150)
            ctx = Context(img)
            ctx.font = ROBO
            ctx.fontSize = 50f0
            strokeText(ctx, "Hello world", 50f0, 90f0)
            check0("font_ctx_stroke1", img)
        end
        @testset "ubuntu1 (Ubuntu 24 'Word')" begin
            f = newFont(tf2); f.size = 24f0
            img = white200()
            fillText(img, f, "Word")
            check0("font_ubuntu1", img)
        end
    end

    @testset "context text state and measureText" begin
        img = newImage(100, 100)
        ctx = Context(img)
        ctx.font = ROBO
        # test_contexts.nim L494-495: default size 12, width == 60.
        @test isequal(measureText(ctx, "Hello world").width, 60f0)

        # save/restore: font/fontSize/textAlign/lineDash restored;
        # textBaseline is NOT part of the saved state (upstream quirk).
        ctx.fontSize = 20f0
        ctx.textBaseline = TopBaseline
        save(ctx)
        ctx.fontSize = 30f0
        ctx.textAlign = RightAlign
        setLineDash(ctx, Float32[5, 6])
        restore(ctx)
        @test ctx.fontSize == 20f0
        @test ctx.textAlign == LeftAlign
        @test ctx.lineDash == Float32[]
        @test ctx.textBaseline === TopBaseline

        # setLineDash/getLineDash round trip.
        setLineDash(ctx, Float32[1, 2, 3])
        @test getLineDash(ctx) == Float32[1, 2, 3]

        # No font set.
        ctx2 = Context(newImage(4, 4))
        @test throws_arg(() -> fillText(ctx2, "x", 1f0, 1f0),
            "No font has been set on this Context")
        @test throws_arg(() -> strokeText(ctx2, "x", 1f0, 1f0),
            "No font has been set on this Context")
        @test throws_arg(() -> measureText(ctx2, "x"),
            "No font has been set on this Context")
    end

    @testset "malformed font bytes are rejected" begin
        robo = Vector{UInt8}(read(ROBO))

        # 1-based directory record start for a tag (record: tag 4,
        # checksum 4, offset 4, length 4).
        function recordbase(buf::Vector{UInt8}, tag::String)
            nt = (Int(buf[5]) << 8 | Int(buf[6]))
            for j in 1:nt
                base = 13 + 16 * (j - 1)
                String(buf[base:(base + 3)]) == tag && return base
            end
            return nothing
        end
        tableoff(buf::Vector{UInt8}, tag::String) = begin
            base = recordbase(buf, tag)
            # tag(4) checksum(4) offset(4) length(4); Int() before << or
            # UInt8 wraps the shift to 0.
            (Int(buf[base + 8]) << 24 | Int(buf[base + 9]) << 16 |
                Int(buf[base + 10]) << 8 | Int(buf[base + 11])) + 1
        end

        @test throws_arg(() -> parseOpenType(robo[1:100]),
            "Unexpected error reading font data, EOF")

        # Corrupt the cmap directory tag -> table missing.
        r = copy(robo)
        b = recordbase(r, "cmap")
        r[b:(b + 3)] = codeunits("cmxp")
        @test throws_arg(() -> parseOpenType(r),
            "Missing required font table: cmap")

        r = copy(robo)
        t = tableoff(r, "head")
        r[t + 1] = 0x02 # major version 2
        @test throws_arg(() -> parseOpenType(r),
            "Unsupported font Head major version")

        r = copy(robo)
        t = tableoff(r, "maxp")
        r[t] = 0x00; r[t + 1] = 0x02 # version 0.2
        @test throws_arg(() -> parseOpenType(r),
            "Unsupported font Maxp version")

        # CFF-only font (Inter) raises at outline selection.
        @test throws_arg(() -> readTypeface(INTER),
            "Unsupported font CFF outlines")
        # SVG fonts are outside the D015 subset.
        @test throws_arg(() -> readTypeface("/nonexistent/font.svg"),
            "Unsupported font format")
    end

    @testset "textCase conversion (pinned Nim case tables)" begin
        f = newFont(readTypeface(ROBO))
        f.size = 24f0
        f.textCase = UpperCase
        @test typeset(f, "abc").runes == UInt32[65, 66, 67]
        f.textCase = LowerCase
        @test typeset(f, "ABC").runes == UInt32[97, 98, 99]
        # TitleCase uppercases after each whitespace rune; upstream seeds
        # prevRune with SP, so the first rune counts.
        f.textCase = TitleCase
        @test typeset(f, "hello world").runes ==
            UInt32[72, 101, 108, 108, 111, 32, 87, 111, 114, 108, 100]
        f.textCase = NormalCase
        @test typeset(f, "abc").runes == UInt32[97, 98, 99]
        # Direct table probes: expectations from the pinned Nim 2.2.6
        # unicase tables (toUpperSinglets µ→Μ; toLowerRanges Õ-range
        # block: Å U+00C5 → å U+00E5; ß has no simple mapping).
        @test Vetra._otToUpper(UInt32(0x00b5)) == UInt32(0x039c)
        @test Vetra._otToLower(UInt32(0x00c5)) == UInt32(0x00e5)
        @test Vetra._otToUpper(UInt32(0x00df)) == UInt32(0x00df)
    end

    @testset "typeface fallbacks: hasGlyph vs fallbackTypeface" begin
        ro = readTypeface(ROBO)
        ub = readTypeface(UBU)
        main = Typeface(ro.opentype, "")
        main.fallbacks = [ub]
        # U+0180 maps in Ubuntu's cmap but not Roboto's (probe above).
        @test !hasGlyph(main, UInt32(0x0180)) # upstream: no fallback walk
        fb = fallbackTypeface(main, UInt32(0x0180))
        @test fb !== nothing
        @test hasGlyph(fb, UInt32(0x0180))
        @test fallbackTypeface(main, UInt32(87)) === main
        @test fallbackTypeface(main, UInt32(0x1f600)) === nothing
    end

    @testset "rounding ties away from zero (upstream Nim round)" begin
        # Verified against the pinned toolchain: round(-1.5f) == -2,
        # round(-0.5f) == -1 (C roundf semantics).
        @test Vetra.roundHalfAway(-1.5f0) == -2
        @test Vetra.roundHalfAway(-0.5f0) == -1
        @test Vetra.roundHalfAway(0.5f0) == 1
        @test Vetra.roundHalfAway(1.5f0) == 2
        @test Vetra.roundHalfAway(-2.2f0) == -2
        @test Vetra.roundHalfAway(2.8f0) == 3
    end

    @testset "GPOS value format size counts all 16 bits" begin
        @test Vetra._otValueFormatSize(0xffff) == 32
        @test Vetra._otValueFormatSize(4) == 2
        @test Vetra._otValueFormatSize(0) == 0
    end

    @testset "name text decoding (flatty fromUTF16BE semantics)" begin
        be16n(v::Int) = UInt8[(v >> 8) & 0xff, v & 0xff]
        mkname(s) = vcat(be16n(0), be16n(1), be16n(18),
            be16n(3), be16n(1), be16n(1033), be16n(6), be16n(length(s)),
            be16n(0), s)
        # Surrogate pair D83D DE00 combines to U+1F600.
        rec = Vetra._otParseName(
            mkname(UInt8[0xd8, 0x3d, 0xde, 0x00, 0x00, 0x41, 0x00, 0x42]), 1)
        @test rec.records[1][3] == "😀AB"
        # Unpaired high surrogate becomes tofu (U+25A1).
        rec = Vetra._otParseName(
            mkname(UInt8[0xd8, 0x35, 0x41, 0x42]), 1)
        @test rec.records[1][3] == "□"
        # A trailing odd byte is dropped, not an error.
        rec = Vetra._otParseName(mkname(UInt8[0x00, 0x42, 0x43]), 1)
        @test rec.records[1][3] == "B"
    end

    @testset "empty text layout" begin
        f = newFont(readTypeface(ROBO))
        f.size = 24f0
        arr = typeset(f, "")
        @test isempty(arr.runes)
        @test layoutBounds(arr) == Vec2(0f0, 0f0)
    end

    # ---------- synthetic mini font ----------
    # Hand-built TTF (spec-derived): 4 glyphs — 0: .notdef (empty, equal
    # loca offsets), 1: 'A' (4-point square, on-curve), 2: 'B' (composite
    # of A + the empty .notdef), 3: 'C' (numberOfContours = 0). Exercises
    # composite glyphs, both empty-glyph modes, hmtx trailing LSBs,
    # OS/2 v2 sCapHeight, UTF-16BE name decode, kern v0 (no GPOS) and the
    # GPOS-absent kerning path.
    @testset "synthetic mini font" begin
        be16(v::Integer) = UInt8[(v >> 8) & 0xff, v & 0xff]
        be32(v::Integer) =
            UInt8[(v >> 24) & 0xff, (v >> 16) & 0xff, (v >> 8) & 0xff,
                v & 0xff]
        b16(v::Integer) = be16(v & 0xffff)

        head = vcat(
            be32(0x0001_0000), be32(0), be32(0), be32(0x5f0f_3cf5),
            be16(0), be16(100), zeros(UInt8, 16), zeros(UInt8, 8),
            be16(0), be16(0), be16(0), be16(1), be16(0))
        @test length(head) == 54
        hhea = vcat(be16(1), be16(0), b16(80), b16(-20), be16(0), be16(50),
            b16(0), b16(0), b16(0), b16(1), be16(0), be16(0),
            zeros(UInt8, 8), be16(0), be16(2))
        @test length(hhea) == 36
        maxp = vcat(be32(0x0001_0000), be16(4), be16(4), be16(1),
            be16(0), be16(0), be16(2), be16(0), be16(0), be16(0),
            be16(0), be16(0), be16(0), be16(2), be16(1))
        @test length(maxp) == 32
        hmtx = vcat(be16(20), b16(0), be16(50), b16(10), b16(7), b16(9))
        # cmap: upstream reads a 14-byte format-4 header (searchRange,
        # entrySelector, rangeShift before endCodes -- its own layout).
        # cmap: upstream reads a non-standard 14-byte format-4 header
        # (searchRange, entrySelector, rangeShift before endCodes). All
        # three segments use the same delta (-64), so no range offsets.
        cmap = vcat(
            be16(0), be16(1), be16(3), be16(1), be32(12),
            be16(4), be16(48), be16(0), be16(8),
            be16(4), be16(2), be16(6),
            be16(65), be16(66), be16(67), be16(0xffff),
            be16(0),
            be16(65), be16(66), be16(67), be16(0xffff),
            be16(0xffc0), be16(0xffc0), be16(0xffc0), be16(0),
            be16(0), be16(0), be16(0), be16(0))
        @test length(cmap) == 60
        utf16be(s::String) =
            vcat([UInt8[0, cp] for cp in (Int(s[i]) for i in 1:length(s))]...)
        namerec = vcat(be16(3), be16(1), be16(1033), be16(6),
            be16(length("MiniFont") * 2), be16(0))
        # (Local name is `nameTable`: `name` is the exported font API.)
        # storageOffset = 6 + 12 (one record) = 18.
        nameTable =
            vcat(be16(0), be16(1), be16(18), namerec, utf16be("MiniFont"))
        # OS/2 in upstream's layout: vendID(4) + fsSelection(2) follow the
        # unicode ranges; v0 = 78 bytes, v1 += 8, v2 += 10 (sxHeight @86,
        # sCapHeight @88, ...).
        os2 = vcat(
            be16(2), b16(50), be16(400), be16(5), be16(0),
            b16(700), b16(500), b16(0), b16(140),
            b16(700), b16(500), b16(0), b16(500),
            b16(50), b16(100), b16(0),
            zeros(UInt8, 10), zeros(UInt8, 16), zeros(UInt8, 4),
            be16(0), be16(65), be16(67), b16(80), b16(-20), be16(0),
            be16(80), be16(20), zeros(UInt8, 8),
            b16(75), b16(123), be16(32), be16(10), be16(3))
        @test length(os2) == 96
        post = vcat(be32(0x0003_0000), be32(0), b16(-10), b16(4),
            be32(0), be16(0))
        @test length(post) == 18
        loca = vcat(be32(0), be32(0), be32(34), be32(60))
        # 'A': square (10,10)-(50,90), all on-curve, int16 deltas.
        glyphA = vcat(b16(1), b16(10), b16(10), b16(50), b16(90), be16(3),
            be16(0), UInt8[1, 1, 1, 1],
            b16(10), b16(40), b16(0), b16(-40),
            b16(10), b16(0), b16(80), b16(0))
        @test length(glyphA) == 34
        # 'B': composite: A at (0,0), .notdef at (60,0). A composite record
        # is numberOfContours = -1 + 8 unused bbox bytes, then components.
        # Upstream treats bit 5 (0x20) -- not the spec's 0x400 -- as
        # MORE_COMPONENTS.
        glyphB = vcat(b16(-1), zeros(UInt8, 8),
            be16(0x0023), be16(1), b16(0), b16(0),
            be16(0x0003), be16(0), b16(60), b16(0))
        @test length(glyphB) == 26
        # 'C': numberOfContours = 0 (empty).
        glyphC = vcat(b16(0), zeros(UInt8, 8))
        @test length(glyphC) == 10
        glyf = vcat(glyphA, glyphB, glyphC)
        @test length(glyf) == 70
        # kern v0: one subtable, horizontal accumulate, pair (A, C) = -3.
        kern = vcat(be16(0), be16(1),
            be16(0), be16(20), be16(1), be16(1), be16(2), be16(0), be16(0),
            be16(1), be16(3), b16(-3))
        @test length(kern) == 24

        let
            # 11 records: directory = 12 + 11*16 = 188 bytes, so tables
            # start at 1-based byte 189.
            tables = [
                ("head", head, 189),
                ("hhea", hhea, 243),
                ("maxp", maxp, 279),
                ("hmtx", hmtx, 311),
                ("cmap", cmap, 323),
                ("name", nameTable, 383),
                ("OS/2", os2, 417),
                ("post", post, 513),
                ("loca", loca, 531),
                ("glyf", glyf, 547),
                ("kern", kern, 617),
            ]
            buf = zeros(UInt8, 640)
            buf[1:4] = be32(0x0001_0000)
            buf[5:6] = be16(length(tables))
            buf[7:8] = be16(64)
            buf[9:10] = be16(1)
            buf[11:12] = be16(0)
            for (idx, (tag, tbl, off)) in enumerate(tables)
                base = 13 + 16 * (idx - 1)
                buf[base:(base + 3)] = codeunits(tag)
                buf[base + 4:(base + 7)] = be32(0)
                buf[base + 8:(base + 11)] = be32(off - 1)
                buf[base + 12:(base + 15)] = be32(length(tbl))
                buf[off:(off + length(tbl) - 1)] = tbl
            end
            global minibuf = buf
        end

        tf = parseTtf(minibuf)
        @test name(tf) == "MiniFont"
        @test scale(tf) == 100f0
        @test ascent(tf) == 80f0
        @test descent(tf) == -20f0
        @test lineGap(tf) == 0f0
        @test lineHeight(tf) == 100f0
        @test capHeight(tf) == 123f0 # OS/2 v2
        @test tf.opentype.post.underlinePosition == -10
        @test tf.opentype.post.underlineThickness == 4

        @test hasGlyph(tf, UInt32(65))
        @test hasGlyph(tf, UInt32(66))
        @test hasGlyph(tf, UInt32(67))
        @test !hasGlyph(tf, UInt32(68))
        @test Int(tf.opentype.cmap.runeToGlyphId[UInt32(65)]) == 1
        @test Int(tf.opentype.cmap.runeToGlyphId[UInt32(66)]) == 2
        @test Int(tf.opentype.cmap.runeToGlyphId[UInt32(67)]) == 3

        # hmtx: A from hMetrics, B/C fall back to the last advance (50).
        # Upstream getLeftSideBearing guards the tail with `index > 0`, so
        # B (first trailing glyph, tail value 7) reports lsb 0; C reports 9.
        @test isequal(getAdvance(tf.opentype, UInt32(65)), 50f0)
        @test isequal(getAdvance(tf.opentype, UInt32(66)), 50f0)
        @test isequal(getAdvance(tf.opentype, UInt32(67)), 50f0)
        @test isequal(getLeftSideBearing(tf.opentype, UInt32(65)), 10f0)
        @test isequal(getLeftSideBearing(tf.opentype, UInt32(66)), 0f0)
        @test isequal(getLeftSideBearing(tf.opentype, UInt32(67)), 9f0)

        # kern v0 (no GPOS on this font): (A, C) = -3, others 0.
        @test isequal(getKerningAdjustment(tf, UInt32(65), UInt32(67)), -3f0)
        @test isequal(getKerningAdjustment(tf, UInt32(65), UInt32(66)), 0f0)
        @test isequal(getKerningAdjustment(tf, UInt32(67), UInt32(65)), 0f0)

        # Glyph outlines: A square (after the Y flip), B composite, C empty.
        @test computeBounds(getGlyphPath(tf, UInt32(65))) ==
            Rect(10f0, -90f0, 40f0, 80f0)
        @test computeBounds(getGlyphPath(tf, UInt32(66))) ==
            Rect(10f0, -90f0, 40f0, 80f0)
        @test computeBounds(getGlyphPath(tf, UInt32(67))) == Rect(0f0, 0f0, 0f0, 0f0)

        # Layout: "AC" @100 (scale 1) with the -3 kern; "AB" without it.
        f = newFont(tf)
        f.size = 100f0
        @test layoutBounds(f, "AC") == Vec2(97f0, 100f0)
        @test layoutBounds(f, "AB") == Vec2(100f0, 100f0)
        @test isequal(defaultLineHeight(f), 100f0)

        # Render: 'A' (square x10..50, font y10..90) via a downward
        # translate so the capital (which sits fully above the baseline)
        # lands inside the image. baseline(TopAlign)=80, +30 -> 110;
        # 'A' spans image y 20..100, x 10..50.
        img2 = newImage(200, 200)
        fill(img2, rgb(255, 255, 255))
        fillText(img2, f, "A", transform = translate(Vec2(0f0, 30f0)))
        rch = (x, y) -> Int(img2.data[4 * ((y - 1) * 200 + (x - 1)) + 1])
        @test rch(30, 60) < 128   # inside the square
        @test rch(30, 15) == 255  # above
        @test rch(30, 105) == 255 # below
        @test rch(5, 60) == 255   # left
        @test rch(55, 60) == 255  # right

        # OS/2 v1 variant: sCapHeight stays 0.
        r = copy(minibuf)
        r[417:418] = be16(1)
        @test capHeight(parseTtf(r)) == 0f0

        # maxp v0.5 variant (16.16 fixed 0.5 = 0x5000): parses, same
        # numGlyphs-driven metrics.
        r = copy(minibuf)
        r[279:282] = be32(0x0000_5000)
        tf5 = parseTtf(r)
        @test isequal(getAdvance(tf5.opentype, UInt32(65)), 50f0)

        # post invalid version: major nibble 10 fails the 16.16 check.
        r = copy(minibuf)
        r[513:516] = be32(0x000a_0000)
        @test throws_arg(() -> parseTtf(r),
            "Unsupported font invalid version format")

        # loca format 0 variant: halve the loca offsets (all even);
        # head.indexToLocFormat = 0 (head @1-based 189, field @+50).
        r = copy(minibuf)
        r[239:240] = be16(0)
        r[531:532] = be16(0)
        r[533:534] = be16(0)
        r[535:536] = be16(17)
        r[537:538] = be16(30)
        tf0 = parseTtf(r)
        @test isequal(getAdvance(tf0.opentype, UInt32(65)), 50f0)
        @test computeBounds(getGlyphPath(tf0, UInt32(65))) ==
            Rect(10f0, -90f0, 40f0, 80f0)

        # kern v1 (Mac) variant: the table is skipped, kerning is 0.
        r = copy(minibuf)
        r[618] = 0x01 # version u16 low byte (kern @617)
        @test isequal(getKerningAdjustment(parseTtf(r), UInt32(65), UInt32(67)),
            0f0)
    end
end
